#!/usr/bin/env python3
import os
import tempfile
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = 8080
RECORDS_DIR = "/var/lib/builder-app/records"


def record_path(record_id):
    if not record_id or "/" in record_id or "\\" in record_id or record_id in (".", ".."):
        return None
    return os.path.join(RECORDS_DIR, record_id)


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "BuilderApp/1.0"

    def _read_body(self):
        length = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(length) if length > 0 else b""

    def _send(self, status, body=b"", content_type="application/octet-stream"):
        self.send_response(status)
        if status != 204:
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
        else:
            self.send_header("Content-Length", "0")
        self.end_headers()
        if status != 204 and body:
            self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self._send(200, b"ready", "text/plain")
            return
        if self.path.startswith("/records/"):
            path = record_path(self.path[len("/records/"):])
            if path is None:
                self._send(400)
                return
            try:
                with open(path, "rb") as f:
                    self._send(200, f.read())
            except FileNotFoundError:
                self._send(404, b"not found", "text/plain")
            return
        self._send(404, b"not found", "text/plain")

    def do_PUT(self):
        if not self.path.startswith("/records/"):
            self._send(404, b"not found", "text/plain")
            return
        path = record_path(self.path[len("/records/"):])
        if path is None:
            self._send(400)
            return
        body = self._read_body()
        os.makedirs(RECORDS_DIR, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=RECORDS_DIR, prefix=".tmp-")
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(body)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, path)
            dir_fd = os.open(RECORDS_DIR, os.O_RDONLY)
            try:
                os.fsync(dir_fd)
            finally:
                os.close(dir_fd)
        except BaseException:
            try:
                os.unlink(tmp)
            except OSError:
                pass
            raise
        self._send(204)

    def do_HEAD(self):
        if self.path == "/health":
            self._send(200, b"ready", "text/plain")
        else:
            self._send(404, b"not found", "text/plain")

    def log_message(self, fmt, *args):
        pass


if __name__ == "__main__":
    os.makedirs(RECORDS_DIR, exist_ok=True)
    server = ThreadingHTTPServer(("0.0.0.0", PORT), Handler)
    server.serve_forever()

